INSERT INTO glosses(id,locale,text,usage_label,source_id,status) VALUES
  ('gloss-word-suiran','id','meskipun; walaupun','Biasanya dipasangkan dengan 但是 untuk menyatakan dua hal yang berlawanan.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-danshi','id','tetapi; namun','Menghubungkan dua bagian kalimat yang isinya berlawanan.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-yinwei','id','karena','Menjelaskan alasan; dapat diikuti klausa hasil yang diawali 所以.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-suoyi','id','jadi; oleh karena itu','Memperkenalkan hasil atau akibat dari alasan yang disebutkan.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-ruguo','id','jika; kalau','Mengajukan syarat; bagian hasil sering menggunakan 就.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-keneng','id','mungkin; barangkali','Menunjukkan bahwa sesuatu mungkin terjadi, bukan kepastian.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-yinggai','id','sebaiknya; seharusnya','Menyatakan saran atau dugaan yang cukup kuat; diikuti kata kerja atau klausa.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-juede','id','merasa; berpendapat','Menyampaikan pendapat atau kesan pribadi, biasanya diikuti klausa atau kata sifat.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-yijing','id','sudah; telah','Menunjukkan keadaan atau tindakan yang sudah terjadi; sering muncul sebelum kata kerja.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-hai','id','masih; juga; tambahan','Dalam pola 还在 menyatakan kegiatan atau keadaan yang masih berlangsung.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-zhengzai','id','sedang','Diletakkan sebelum kata kerja untuk menekankan bahwa kegiatan sedang berlangsung.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-yiqian','id','dulu; sebelumnya','Menunjukkan waktu sebelum waktu acuan; dapat diletakkan di awal atau setelah topik.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-yihou','id','setelah; nanti; kelak','Menunjukkan waktu setelah suatu kegiatan atau waktu acuan.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-meitian','id','setiap hari','Keterangan frekuensi yang biasanya diletakkan sebelum kata kerja.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-xian','id','lebih dahulu; pertama','Menandai tindakan yang dilakukan lebih dahulu; sering dipasangkan dengan 再.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-houlai','id','kemudian; setelah itu','Menceritakan kejadian berikutnya dalam urutan waktu lampau.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-mingbai','id','mengerti; paham','Menyatakan bahwa makna atau maksud sudah dipahami.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-qingchu','id','jelas','Untuk informasi, suara, tulisan, atau pemahaman yang tidak samar.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-dangran','id','tentu saja','Menegaskan persetujuan atau sesuatu yang dianggap wajar.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-faxian','id','menemukan; menyadari','Mengetahui sesuatu yang sebelumnya belum disadari atau diketahui.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-jieshi','id','menjelaskan; penjelasan','Membuat makna, alasan, atau aturan lebih mudah dipahami.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-xuanze','id','memilih; pilihan','Menentukan satu dari beberapa kemungkinan.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-zhongyao','id','penting','Menilai bahwa seseorang atau sesuatu memiliki arti atau prioritas besar.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-fangbian','id','praktis; mudah; nyaman','Menggambarkan sesuatu yang mudah dilakukan atau cocok dari sisi waktu dan keadaan.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-fuxi','id','mengulang pelajaran','Mempelajari kembali materi yang pernah dipelajari agar lebih kuat diingat.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-lianxi','id','berlatih; latihan','Melakukan kegiatan berulang untuk meningkatkan kemampuan.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-jinbu','id','maju; berkembang','Menyatakan kemampuan atau keadaan menjadi lebih baik.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-cuowu','id','kesalahan; keliru','Dapat menjadi kata benda untuk kesalahan atau muncul dalam ungkapan 做错了.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-juzi','id','kalimat','Rangkaian kata yang menyampaikan satu gagasan.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-yisi','id','arti; maksud','Menanyakan atau menjelaskan makna kata, kalimat, atau tindakan.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-jide','id','ingat; jangan lupa','Menyatakan masih mengingat sesuatu; juga digunakan dalam pola 记得做.','source-course-expansion-2026-09-foundation','approved'),
  ('gloss-word-wangji','id','lupa; melupakan','Menyatakan sesuatu tidak lagi diingat; dapat diikuti orang atau tindakan.','source-course-expansion-2026-09-foundation','approved');
