INSERT INTO examples(id,vocabulary_id,character_id,simplified_text,pinyin_json,numbered_pinyin,locale,translation,source_id,status) VALUES
  ('example-word-suiran','word-suiran',NULL,'虽然下雨，但是我们还是去。','["suī","rán","xià","yǔ","dàn","shì","wǒ","men","hái","shì","qù"]','sui1 ran2 xia4 yu3 dan4 shi4 wo3 men0 hai2 shi4 qu4','id','Meskipun hujan, kami tetap pergi.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-danshi','word-danshi',NULL,'我想去，但是今天很忙。','["wǒ","xiǎng","qù","dàn","shì","jīn","tiān","hěn","máng"]','wo3 xiang3 qu4 dan4 shi4 jin1 tian1 hen3 mang2','id','Saya ingin pergi, tetapi hari ini sangat sibuk.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-yinwei','word-yinwei',NULL,'因为下雨，所以我在家。','["yīn","wèi","xià","yǔ","suǒ","yǐ","wǒ","zài","jiā"]','yin1 wei4 xia4 yu3 suo3 yi3 wo3 zai4 jia1','id','Karena hujan, saya berada di rumah.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-suoyi','word-suoyi',NULL,'我很累，所以想休息。','["wǒ","hěn","lèi","suǒ","yǐ","xiǎng","xiū","xi"]','wo3 hen3 lei4 suo3 yi3 xiang3 xiu1 xi0','id','Saya sangat lelah, jadi ingin beristirahat.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-ruguo','word-ruguo',NULL,'如果你有时间，我们就一起吃饭。','["rú","guǒ","nǐ","yǒu","shí","jiān","wǒ","men","jiù","yì","qǐ","chī","fàn"]','ru2 guo3 ni3 you3 shi2 jian1 wo3 men0 jiu4 yi4 qi3 chi1 fan4','id','Kalau kamu punya waktu, kita makan bersama.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-keneng','word-keneng',NULL,'他可能还在学校。','["tā","kě","néng","hái","zài","xué","xiào"]','ta1 ke3 neng2 hai2 zai4 xue2 xiao4','id','Dia mungkin masih di sekolah.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-yinggai','word-yinggai',NULL,'你应该多练习汉字。','["nǐ","yīng","gāi","duō","liàn","xí","hàn","zì"]','ni3 ying1 gai1 duo1 lian4 xi2 han4 zi4','id','Kamu sebaiknya lebih banyak berlatih hanzi.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-juede','word-juede',NULL,'我觉得这个办法很好。','["wǒ","jué","de","zhè","ge","bàn","fǎ","hěn","hǎo"]','wo3 jue2 de0 zhe4 ge0 ban4 fa3 hen3 hao3','id','Menurut saya, cara ini sangat baik.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-yijing','word-yijing',NULL,'我已经做完今天的练习。','["wǒ","yǐ","jīng","zuò","wán","jīn","tiān","de","liàn","xí"]','wo3 yi3 jing1 zuo4 wan2 jin1 tian1 de0 lian4 xi2','id','Saya sudah menyelesaikan latihan hari ini.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-hai','word-hai',NULL,'她还在学习中文。','["tā","hái","zài","xué","xí","zhōng","wén"]','ta1 hai2 zai4 xue2 xi2 zhong1 wen2','id','Dia masih belajar bahasa Mandarin.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-zhengzai','word-zhengzai',NULL,'妈妈正在做饭。','["mā","ma","zhèng","zài","zuò","fàn"]','ma1 ma0 zheng4 zai4 zuo4 fan4','id','Ibu sedang memasak.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-yiqian','word-yiqian',NULL,'我以前住在雅加达。','["wǒ","yǐ","qián","zhù","zài","yǎ","jiā","dá"]','wo3 yi3 qian2 zhu4 zai4 ya3 jia1 da2','id','Dulu saya tinggal di Jakarta.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-yihou','word-yihou',NULL,'下课以后，我们一起复习。','["xià","kè","yǐ","hòu","wǒ","men","yì","qǐ","fù","xí"]','xia4 ke4 yi3 hou4 wo3 men0 yi4 qi3 fu4 xi2','id','Setelah kelas, kita mengulang pelajaran bersama.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-meitian','word-meitian',NULL,'她每天写汉字。','["tā","měi","tiān","xiě","hàn","zì"]','ta1 mei3 tian1 xie3 han4 zi4','id','Dia menulis hanzi setiap hari.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-xian','word-xian',NULL,'我们先吃饭，再去学校。','["wǒ","men","xiān","chī","fàn","zài","qù","xué","xiào"]','wo3 men0 xian1 chi1 fan4 zai4 qu4 xue2 xiao4','id','Kita makan dulu, lalu pergi ke sekolah.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-houlai','word-houlai',NULL,'我先不明白，后来终于懂了。','["wǒ","xiān","bù","míng","bai","hòu","lái","zhōng","yú","dǒng","le"]','wo3 xian1 bu4 ming2 bai0 hou4 lai2 zhong1 yu2 dong3 le0','id','Awalnya saya belum paham, kemudian akhirnya mengerti.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-mingbai','word-mingbai',NULL,'老师说得很慢，我都明白。','["lǎo","shī","shuō","de","hěn","màn","wǒ","dōu","míng","bai"]','lao3 shi1 shuo1 de0 hen3 man4 wo3 dou1 ming2 bai0','id','Guru berbicara dengan lambat, jadi saya mengerti semuanya.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-qingchu','word-qingchu',NULL,'请说清楚一点。','["qǐng","shuō","qīng","chu","yì","diǎn"]','qing3 shuo1 qing1 chu0 yi4 dian3','id','Tolong berbicaralah sedikit lebih jelas.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-dangran','word-dangran',NULL,'你可以用我的词典，当然可以。','["nǐ","kě","yǐ","yòng","wǒ","de","cí","diǎn","dāng","rán","kě","yǐ"]','ni3 ke3 yi3 yong4 wo3 de0 ci2 dian3 dang1 ran2 ke3 yi3','id','Kamu boleh memakai kamus saya, tentu saja boleh.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-faxian','word-faxian',NULL,'我发现这个字写错了。','["wǒ","fā","xiàn","zhè","ge","zì","xiě","cuò","le"]','wo3 fa1 xian4 zhe4 ge0 zi4 xie3 cuo4 le0','id','Saya menyadari bahwa hanzi ini salah ditulis.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-jieshi','word-jieshi',NULL,'请再解释一次这个语法。','["qǐng","zài","jiě","shì","yí","cì","zhè","ge","yǔ","fǎ"]','qing3 zai4 jie3 shi4 yi2 ci4 zhe4 ge0 yu3 fa3','id','Tolong jelaskan tata bahasa ini sekali lagi.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-xuanze','word-xuanze',NULL,'这两个办法都可以，你选择一个吧。','["zhè","liǎng","ge","bàn","fǎ","dōu","kě","yǐ","nǐ","xuǎn","zé","yí","ge","ba"]','zhe4 liang3 ge0 ban4 fa3 dou1 ke3 yi3 ni3 xuan3 ze2 yi2 ge0 ba0','id','Kedua cara ini bisa; pilih salah satu.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-zhongyao','word-zhongyao',NULL,'每天复习很重要。','["měi","tiān","fù","xí","hěn","zhòng","yào"]','mei3 tian1 fu4 xi2 hen3 zhong4 yao4','id','Mengulang pelajaran setiap hari itu penting.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-fangbian','word-fangbian',NULL,'用手机查词很方便。','["yòng","shǒu","jī","chá","cí","hěn","fāng","biàn"]','yong4 shou3 ji1 cha2 ci2 hen3 fang1 bian4','id','Mencari kata dengan ponsel itu praktis.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-fuxi','word-fuxi',NULL,'我每天复习十个新词。','["wǒ","měi","tiān","fù","xí","shí","ge","xīn","cí"]','wo3 mei3 tian1 fu4 xi2 shi2 ge0 xin1 ci2','id','Saya mengulang sepuluh kosakata baru setiap hari.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-lianxi','word-lianxi',NULL,'她正在练习写汉字。','["tā","zhèng","zài","liàn","xí","xiě","hàn","zì"]','ta1 zheng4 zai4 lian4 xi2 xie3 han4 zi4','id','Dia sedang berlatih menulis hanzi.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-jinbu','word-jinbu',NULL,'多听多说，中文会进步。','["duō","tīng","duō","shuō","zhōng","wén","huì","jìn","bù"]','duo1 ting1 duo1 shuo1 zhong1 wen2 hui4 jin4 bu4','id','Banyak mendengar dan berbicara akan membuat kemampuan Mandarin berkembang.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-cuowu','word-cuowu',NULL,'写错了不要怕，改正就好。','["xiě","cuò","le","bú","yào","pà","gǎi","zhèng","jiù","hǎo"]','xie3 cuo4 le0 bu2 yao4 pa4 gai3 zheng4 jiu4 hao3','id','Jangan takut saat salah menulis; perbaiki saja.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-juzi','word-juzi',NULL,'请用这个词说一个句子。','["qǐng","yòng","zhè","ge","cí","shuō","yí","ge","jù","zi"]','qing3 yong4 zhe4 ge0 ci2 shuo1 yi2 ge0 ju4 zi0','id','Tolong gunakan kata ini untuk membuat satu kalimat.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-yisi','word-yisi',NULL,'这个词是什么意思？','["zhè","ge","cí","shì","shén","me","yì","si"]','zhe4 ge0 ci2 shi4 shen2 me0 yi4 si0','id','Apa arti kata ini?','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-jide','word-jide',NULL,'记得每天练习写字。','["jì","de","měi","tiān","liàn","xí","xiě","zì"]','ji4 de0 mei3 tian1 lian4 xi2 xie3 zi4','id','Ingatlah untuk berlatih menulis setiap hari.','source-course-expansion-2026-09-foundation','approved'),
  ('example-word-wangji','word-wangji',NULL,'我忘记了这个汉字的读音。','["wǒ","wàng","jì","le","zhè","ge","hàn","zì","de","dú","yīn"]','wo3 wang4 ji4 le0 zhe4 ge0 han4 zi4 de0 du2 yin1','id','Saya lupa cara membaca hanzi ini.','source-course-expansion-2026-09-foundation','approved');
